/bin/bash -lc "node --input-type=module <<'EOF'
import { chromium } from '@playwright/test'
import { instant } from '@next/playwright'

const browser = await chromium.launch({ headless: true })
try {
  for (const [category, heading, products] of [
    ['featured', 'Featured products', ['Desk Lamp', 'Wool Blanket']],
    ['sale', 'Products on sale', ['Canvas Tote', 'Travel Mug']],
  ]) {
    const page = await browser.newPage()
    await page.goto('http://127.0.0.1:3099/')
    await page.waitForTimeout(3000)
    await instant(page, async () => {
      await page.locator("'`a[href="/catalog?category=${category}"]`).click()
      await page.getByRole('"'heading', { level: 2, name: heading }).waitFor()
      for (const product of products) await page.getByText(product, { exact: true }).waitFor()
      if (await page.getByText('Loading category...').count()) {
        throw new Error("'`${category}: loading state visible in prefetched navigation`)
      }
      if (new URL(page.url()).searchParams.get('"'category') "'!== category) {
        throw new Error(`${category}: URL category mismatch`)
      }
    })
    console.log(`${category}: prefetched heading and products visible immediately`)
    await page.close()
  }
} finally {
  await browser.close()
}
EOF'

